{
  "verses": [
    {
      "chapter": 7,
      "text_ar": "ولما علموا بذلك، خرجوا من المدينة مع السكان، وأشار إليّ مواطنيّ أمامهم.",
      "verse": 11
    },
    {
      "chapter": 7,
      "text_ar": "ولكن هؤلاء احتجوا وقالوا: \"بالتأكيد، ليس هذا هو أيوب\".",
      "verse": 12
    },
    {
      "chapter": 7,
      "text_ar": "وبينما كانوا مترددين، قال أليفاز، ملك تيمان: \"تعالوا لنقترب ونرى\".",
      "verse": 13
    },
    {
      "chapter": 7,
      "text_ar": "ولما اقتربوا تذكرتهم، وبكيت كثيراً عندما علمت الغاية من رحلتهم.",
      "verse": 14
    },
    {
      "chapter": 7,
      "text_ar": "وألقيت تراباً على رأسي، وبينما كنت أهز رأسي، كشفت لهم أنني أنا [أيوب].",
      "verse": 15
    }
  ],
  "book_code": "TJOB"
}
